const input = $('Grant Intake Webhook').first().json.body || {};
const html  = $input.first().json.data || '';
const text  = html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

const requires_501c3 = /501\(c\)\(3\)|501c3|nonprofit only|non-profit only|tax.exempt organization/i.test(text);
const dlMatch = text.match(/deadline[^:]*:\s*([A-Za-z]+ \d{1,2},?\s*\d{4})/i);

return [{
  json: {
    grant_name:      input.grant_name    || 'Unnamed Grant',
    grant_url:       input.grant_url     || '',
    grantor:         input.grantor       || '',
    grant_amount:    parseFloat(input.grant_amount) || 0,
    deadline:        input.deadline      || (dlMatch ? dlMatch[1] : ''),
    notes:           input.notes         || '',
    requires_501c3,
    content_preview: text.slice(0, 1500),
  },
}];

parameters.text:
=Analyze this grant for Mankind AI Tech (MKAI). MKAI makes AI accessible and operational for small businesses and underserved communities through done-for-you AI agent systems, readiness assessments, and automation.

Respond with ONLY a valid JSON object — no markdown, no explanation — with exactly these fields:
- summary: 2-3 sentence grant summary
- eligible: true or false (is MKAI a strong fit?)
- requires_501c3: true or false
- alignment_1: first specific mission alignment point between MKAI and grantor
- alignment_2: second mission alignment point
- alignment_3: third mission alignment point
- next_step: one concrete immediate action for MKAI
- sop_phase: either "1 - Discover" or "2 - Qualify"

Grant Name: {{ $json.grant_name }}
Grantor: {{ $json.grantor }}
Amount: ${{ $json.grant_amount }}
Deadline: {{ $json.deadline }}
Notes: {{ $json.notes }}

Grant Content Preview:
{{ $json.content_preview }}

parameters.jsCode:
const intake = $('Parse Grant Content').first().json;
const raw    = $input.first().json.output || '{}';

let ai = {};
try {
  const cleaned = raw.replace(/```json|\n```|```/g, '').trim();
  ai = JSON.parse(cleaned);
} catch(e) {
  ai = {
    eligible: true,
    requires_501c3: intake.requires_501c3,
    sop_phase: '1 - Discover',
    summary: 'AI parse failed — review manually.',
    alignment_1: 'Review grant manually for alignment',
    alignment_2: '',
    alignment_3: '',
    next_step: 'Run /grant-writer [URL] in Claude Code for full analysis',
  };
}

return [{
  json: {
    ...intake,
    summary:         ai.summary        || '',
    eligible:        ai.eligible       !== false,
    requires_501c3:  ai.requires_501c3 || intake.requires_501c3 || false,
    alignment_notes: [ai.alignment_1, ai.alignment_2, ai.alignment_3].filter(Boolean).join('\n'),
    next_step:       ai.next_step      || 'Run /grant-writer [URL] in Claude Code',
    sop_phase:       ai.sop_phase      || '1 - Discover',
    status:          ai.eligible === false ? 'Not Eligible' : 'Qualified',
  },
}];
